package measurable_space

import (
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/sets/set_product"
	"github.com/euc-ai/xugo/library/proofs/sets/sigma_algebra"
	"github.com/euc-ai/xugo/library/registry"
)

// ProductSigmaProjections — the product σ-algebra is a σ-algebra on Ω × V
// that holds every measurable rectangle, and both coordinate projections are
// measurable from it. It is generated by the rectangles, which lie in Ω × V;
// an event R of S pulls back under the first coordinate to the rectangle
// R × V, and an event of T under the second to Ω × R.
var ProductSigmaProjections = productSigmaProjectionsThm{family.Add(registry.ProofEntry{
	Name: "ProductSigmaProjections",
	Key:  "prop_15c9ac33e74ff956",
	Build: family.Theorem(Statement{
		Binders:    "∀Ω:set(A). ∀S:set(set(A)). ∀V:set(B). ∀T:set(set(B)).",
		Hypotheses: []string{"sigma_algebra_on(Ω, S)", "sigma_algebra_on(V, T)"},
		Conclusion: "sigma_algebra_on(set_cross(Ω, V), product_sigma(Ω, S, V, T)) ∧ " +
			"(∀s:set(A). ∀t:set(B). s ∈ S ∧ t ∈ T ⇒ set_cross(s, t) ∈ product_sigma(Ω, S, V, T)) ∧ " +
			"measurable_map(set_cross(Ω, V), product_sigma(Ω, S, V, T), Ω, S, λp:prod(A, B). fst(p)) ∧ " +
			"measurable_map(set_cross(Ω, V), product_sigma(Ω, S, V, T), V, T, λp:prod(A, B). snd(p))",
		Abbrev: Abbrev{
			{Name: "productRectangles", Text: "λS:set(set(A)). λT:set(set(B)). " +
				"    {set_cross(s, t):set(prod(A, B)) | s:set(A), t:set(B) | s ∈ S ∧ t ∈ T}"},
		},
	}, func(
		a *Argument,
		Ω *Expr[Set[A]],
		S *Expr[Set[Set[A]]],
		V *Expr[Set[B]],
		T *Expr[Set[Set[B]]],
		sigmas Fact,
	) {
		carrier := a.TermAs[Set[Prod[A, B]]]("set_cross(Ω, V)")
		sigma := a.TermAs[Set[Set[Prod[A, B]]]]("product_sigma(Ω, S, V, T)")
		rectangles := a.TermAs[Set[Set[Prod[A, B]]]]("«productRectangles»(S, T)")
		first := a.TermAs[Fun[Prod[A, B], A]]("λp:prod(A, B). fst(p)")
		second := a.TermAs[Fun[Prod[A, B], B]]("λp:prod(A, B). snd(p)")

		factors := a.Have(
			"the factor events lie in their carriers and include the carriers",
			"S ⊆ {s:set(A) | s ⊆ Ω} ∧ T ⊆ {t:set(B) | t ⊆ V} ∧ Ω ∈ S ∧ V ∈ T",
			By(sigmas, sigma_algebra.SigmaAlgebraOnDef.At(Ω, S), sigma_algebra.SigmaAlgebraOnDef.At(V, T)))
		insideCarrier := a.Have(
			"every measurable rectangle lies in the product carrier",
			"∀s:set(A). ∀t:set(B). s ∈ S ∧ t ∈ T ⇒ set_cross(s, t) ⊆ set_cross(Ω, V)",
			Derive(func(b *Argument) {
				s := b.FixAs[Set[A]]("s")
				t := b.FixAs[Set[B]]("t")
				events := b.Assume()
				inside := b.Have(
					"the two factors are subsets of the carriers",
					"s ⊆ Ω ∧ t ⊆ V",
					BySets(events, factors))
				b.Show(
					"taking the product preserves inclusion",
					By(inside, set_product.CrossSubsetIff.At(s, Ω, t, V)))
			}))
		generators := a.Have(
			"the generators are subsets of the product carrier",
			"«productRectangles»(S, T) ⊆ {R:set(prod(A, B)) | R ⊆ set_cross(Ω, V)}",
			BySets(insideCarrier))
		generated := a.Have(
			"the product σ-algebra contains its generating rectangles",
			"sigma_algebra_on(set_cross(Ω, V), product_sigma(Ω, S, V, T)) ∧ "+
				"«productRectangles»(S, T) ⊆ product_sigma(Ω, S, V, T)",
			By(
				generators,
				sigma_algebra.GeneratedSigmaAlgebra.At(carrier, rectangles),
				ProductSigmaDef.At(Ω, S, V, T)))
		rectangle := a.Have(
			"products of measurable factor events are measurable",
			"∀s:set(A). ∀t:set(B). s ∈ S ∧ t ∈ T ⇒ set_cross(s, t) ∈ product_sigma(Ω, S, V, T)",
			Derive(func(b *Argument) {
				b.FixAs[Set[A]]("s")
				b.FixAs[Set[B]]("t")
				events := b.Assume()
				generator := b.Have(
					"this rectangle belongs to the generators",
					"set_cross(s, t) ∈ «productRectangles»(S, T)",
					BySets(events))
				b.Show(
					"the generated σ-algebra contains it",
					BySets(generated, generator))
			}))
		coordinates := set_product.InCrossProjections.Inst(TypeBinder.BindA[A](), TypeBinder.BindB[B]())
		carrierMembership := a.Have(
			"membership in the product is coordinatewise",
			"∀p:prod(A, B). p ∈ set_cross(Ω, V) ⇔ fst(p) ∈ Ω ∧ snd(p) ∈ V",
			By(At(coordinates, Ω, V)))
		firstImage := a.Have(
			"the first coordinate lies in the first carrier",
			"image(λp:prod(A, B). fst(p), set_cross(Ω, V)) ⊆ Ω",
			BySets(carrierMembership))
		secondImage := a.Have(
			"the second coordinate lies in the second carrier",
			"image(λp:prod(A, B). snd(p), set_cross(Ω, V)) ⊆ V",
			BySets(carrierMembership))
		firstPreimages := a.Have(
			"preimages under the first coordinate are measurable cylinders",
			Statement{
				Binders:    "∀R:set(A).",
				Hypotheses: []string{"R ∈ S"},
				Conclusion: "preimage_on(set_cross(Ω, V), λp:prod(A, B). fst(p), R) ∈ product_sigma(Ω, S, V, T)",
			},
			Derive(func(b *Argument) {
				R := b.FixAs[Set[A]]("R")
				event := b.Assume()
				inside := b.Have(
					"the event lies in its carrier",
					"R ⊆ Ω",
					BySets(event, factors))
				cylinder := b.Have(
					"the preimage is the event times the second carrier",
					"preimage_on(set_cross(Ω, V), λp:prod(A, B). fst(p), R) = set_cross(R, V)",
					BySets(inside, carrierMembership, At(coordinates, R, V)))
				b.Show(
					"the cylinder is a measurable rectangle",
					By(cylinder, event, factors, At(rectangle, R, V)))
			}))
		secondPreimages := a.Have(
			"preimages under the second coordinate are measurable cylinders",
			Statement{
				Binders:    "∀R:set(B).",
				Hypotheses: []string{"R ∈ T"},
				Conclusion: "preimage_on(set_cross(Ω, V), λp:prod(A, B). snd(p), R) ∈ product_sigma(Ω, S, V, T)",
			},
			Derive(func(b *Argument) {
				R := b.FixAs[Set[B]]("R")
				event := b.Assume()
				inside := b.Have(
					"the event lies in its carrier",
					"R ⊆ V",
					BySets(event, factors))
				cylinder := b.Have(
					"the preimage is the first carrier times the event",
					"preimage_on(set_cross(Ω, V), λp:prod(A, B). snd(p), R) = set_cross(Ω, R)",
					BySets(inside, carrierMembership, At(coordinates, Ω, R)))
				b.Show(
					"the cylinder is a measurable rectangle",
					By(cylinder, event, factors, At(rectangle, Ω, R)))
			}))
		a.Show(
			"both coordinates carry measurable sets back into the product σ-algebra",
			By(
				rectangle,
				firstPreimages,
				secondPreimages,
				firstImage,
				secondImage,
				generated,
				MeasurableMapDef.At(carrier, sigma, Ω, S, first),
				MeasurableMapDef.At(carrier, sigma, V, T, second)))
	}),
})}

// ProductSigmaPiSystem — the measurable rectangles form a π-system on the
// product carrier that generates the product σ-algebra: they lie in the
// carrier, and two of them meet in the rectangle of the intersections of
// their factors.
var ProductSigmaPiSystem = productSigmaPiSystemThm{family.Add(registry.ProofEntry{
	Name: "ProductSigmaPiSystem",
	Key:  "prop_2162d0aa76b1b611",
	Build: family.Theorem(Statement{
		Binders:    "∀Ω:set(A). ∀S:set(set(A)). ∀V:set(B). ∀T:set(set(B)).",
		Hypotheses: []string{"sigma_algebra_on(Ω, S)", "sigma_algebra_on(V, T)"},
		Conclusion: "pi_system_on(set_cross(Ω, V), «productRectangles»(S, T)) ∧ " +
			"product_sigma(Ω, S, V, T) = generated_sigma(set_cross(Ω, V), «productRectangles»(S, T))",
		Abbrev: Abbrev{
			{Name: "productRectangles", Text: "λS:set(set(A)). λT:set(set(B)). " +
				"    {set_cross(s, t):set(prod(A, B)) | s:set(A), t:set(B) | s ∈ S ∧ t ∈ T}"},
		},
	}, func(
		a *Argument,
		Ω *Expr[Set[A]],
		S *Expr[Set[Set[A]]],
		V *Expr[Set[B]],
		T *Expr[Set[Set[B]]],
		sigmaS, sigmaT Fact,
	) {
		C, cDef := a.LetAs[Set[Set[Prod[A, B]]]]("C", "«productRectangles»(S, T)")
		carrier := a.TermAs[Set[Prod[A, B]]]("set_cross(Ω, V)")
		factors := a.Have(
			"measurable factors lie in their respective carriers",
			"S ⊆ {s:set(A) | s ⊆ Ω} ∧ T ⊆ {t:set(B) | t ⊆ V}",
			By(
				sigmaS,
				sigmaT,
				sigma_algebra.SigmaAlgebraOnDef.At(Ω, S),
				At(sigma_algebra.SigmaAlgebraOnDef.Inst[B](), V, T)))
		rectangleInside := a.Have(
			"a measurable rectangle lies in the product carrier",
			"∀s:set(A). ∀t:set(B). s ∈ S ∧ t ∈ T ⇒ set_cross(s, t) ⊆ set_cross(Ω, V)",
			Derive(func(b *Argument) {
				s := b.FixAs[Set[A]]("s")
				t := b.FixAs[Set[B]]("t")
				measurable := b.Assume()
				b.Show(
					"each factor lies in its carrier",
					BySets(factors, measurable, set_product.CrossSubsetIff.At(s, Ω, t, V)))
			}))
		inside := a.Have(
			"every generator lies in the product carrier",
			"C ⊆ {R:set(prod(A, B)) | R ⊆ set_cross(Ω, V)}",
			BySets(cDef, rectangleInside))
		rectangleMeet := a.Have(
			"the intersection of two measurable rectangles is another such rectangle",
			"∀s u:set(A). ∀t v:set(B). s ∈ S ∧ u ∈ S ∧ t ∈ T ∧ v ∈ T ⇒ set_cross(s, t) ∩ set_cross(u, v) ∈ C",
			Derive(func(b *Argument) {
				s := b.FixAs[Set[A]]("s")
				u := b.FixAs[Set[A]]("u")
				t := b.FixAs[Set[B]]("t")
				v := b.FixAs[Set[B]]("v")
				measurable := b.Assume()
				factorMeets := b.Have(
					"both intersections of factors are measurable",
					"s ∩ u ∈ S ∧ t ∩ v ∈ T",
					By(
						sigmaS,
						sigmaT,
						measurable,
						sigma_algebra.SigmaFiniteOperations.At(Ω, S),
						At(sigma_algebra.SigmaFiniteOperations.Inst[B](), V, T)))
				rectangle := b.Have(
					"their product belongs to the generators",
					"set_cross(s ∩ u, t ∩ v) ∈ C",
					Simp(Fwd(cDef)),
					By(factorMeets))
				b.Show(
					"intersection of rectangles is the product of the intersections",
					By(Normalized, rectangle, set_product.CrossInter.At(s, u, t, v)))
			}))
		intersections := a.Have(
			"the generating family is closed under intersections",
			"∀R Q:set(prod(A, B)). R ∈ C ∧ Q ∈ C ⇒ R ∩ Q ∈ C",
			Derive(func(b *Argument) {
				b.FixAs[Set[Prod[A, B]]]("R")
				b.FixAs[Set[Prod[A, B]]]("Q")
				members := b.Conjuncts(
					b.Assume(),
					"R is a generating rectangle",
					"Q is a generating rectangle")
				s, t, rectangleR := b.Unpack2As[Set[A], Set[B]](b.Simplified(members[0], Fwd(cDef)), "s", "t")
				u, v, rectangleQ := b.Unpack2As[Set[A], Set[B]](b.Simplified(members[1], Fwd(cDef)), "u", "v")
				b.Show(
					"R ∩ Q is the rectangle (s ∩ u) × (t ∩ v)",
					By(Normalized, rectangleR, rectangleQ, rectangleMeet.At(s, u, t, v)))
			}))
		pi := a.Have(
			"the measurable rectangles form a π-system",
			"pi_system_on(set_cross(Ω, V), C)",
			By(inside, intersections, At(sigma_algebra.PiSystemDef.Inst[Prod[A, B]](), carrier, C)))
		a.Show(
			"by definition the rectangles generate the product σ-algebra",
			By(pi, cDef, ProductSigmaDef.At(Ω, S, V, T)))
	}),
})}

// ProductSigmaSwap — exchanging the two coordinates is measurable from the
// product σ-algebra on V × Ω to the one on Ω × V: it maps the one carrier
// onto the other and pulls each measurable rectangle s × t back to the
// measurable rectangle t × s.
var ProductSigmaSwap = productSigmaSwapThm{family.Add(registry.ProofEntry{
	Name: "ProductSigmaSwap",
	Key:  "prop_45c65f4049b4d021",
	Build: family.Theorem(Statement{
		Binders:    "∀Ω:set(A). ∀S:set(set(A)). ∀V:set(B). ∀T:set(set(B)).",
		Hypotheses: []string{"sigma_algebra_on(Ω, S)", "sigma_algebra_on(V, T)"},
		Conclusion: "measurable_map(set_cross(V, Ω), " +
			"    product_sigma(V, T, Ω, S), " +
			"    set_cross(Ω, V), " +
			"    product_sigma(Ω, S, V, T), " +
			"    «swap»)",
		Abbrev: Abbrev{
			{Name: "rects", Text: "{set_cross(s, t):set(prod(A, B)) | s:set(A), t:set(B) | s ∈ S ∧ t ∈ T}"},
			{Name: "swappedRects", Text: "{set_cross(t, s):set(prod(B, A)) | " +
				"    t:set(B), " +
				"    s:set(A) | " +
				"    t ∈ T ∧ s ∈ S}"},
			{Name: "swap", Text: "λq:prod(B, A). (snd(q), fst(q))"},
		},
	}, func(
		a *Argument,
		Ω *Expr[Set[A]],
		S *Expr[Set[Set[A]]],
		V *Expr[Set[B]],
		T *Expr[Set[Set[B]]],
		sigmaS, sigmaT Fact,
	) {
		K := a.TermAs[Set[Prod[A, B]]]("set_cross(Ω, V)")
		Krev := a.TermAs[Set[Prod[B, A]]]("set_cross(V, Ω)")
		Prev := a.TermAs[Set[Set[Prod[B, A]]]]("product_sigma(V, T, Ω, S)")
		swap := a.TermAs[Fun[Prod[B, A], Prod[A, B]]]("«swap»")
		C, cDef := a.LetAs[Set[Set[Prod[A, B]]]]("C", "«rects»")
		D := a.TermAs[Set[Set[Prod[B, A]]]]("«swappedRects»")
		subsets := a.Have(
			"each measurable factor lies in its carrier",
			"S ⊆ {s:set(A) | s ⊆ Ω} ∧ T ⊆ {t:set(B) | t ⊆ V}",
			By(
				sigmaS,
				sigmaT,
				sigma_algebra.SigmaAlgebraOnDef.At(Ω, S),
				At(sigma_algebra.SigmaAlgebraOnDef.Inst[B](), V, T)))
		rectangles := a.Have(
			"the rectangles lie in their carriers and the swap pulls back a rectangle to the reverse rectangle",
			Statement{
				Binders:    "∀s:set(A). ∀t:set(B).",
				Hypotheses: []string{"s ∈ S", "t ∈ T"},
				Conclusion: "set_cross(s, t) ⊆ set_cross(Ω, V) ∧ " +
					"set_cross(t, s) ⊆ set_cross(V, Ω) ∧ " +
					"preimage_on(set_cross(V, Ω), «swap», set_cross(s, t)) = set_cross(t, s)",
			},
			Derive(func(b *Argument) {
				s := b.FixAs[Set[A]]("s")
				t := b.FixAs[Set[B]]("t")
				member := b.Assume()
				within := b.Have(
					"the factors lie in their carriers",
					"s ⊆ Ω ∧ t ⊆ V",
					BySets(subsets, member))
				carriers := b.Have(
					"take products in both orders",
					"set_cross(s, t) ⊆ set_cross(Ω, V) ∧ set_cross(t, s) ⊆ set_cross(V, Ω)",
					BySets(
						within,
						set_product.CrossSubsetIff.At(s, Ω, t, V),
						set_product.CrossSubsetIff.At(t, V, s, Ω)))
				identity := b.Have(
					"membership in the inverse image is membership in the reversed rectangle",
					"preimage_on(set_cross(V, Ω), «swap», set_cross(s, t)) = set_cross(t, s)",
					BySets(
						carriers,
						set_product.InCross.Inst(TypeBinder.BindA[A](), TypeBinder.BindB[B]()),
						set_product.InCrossProjections.Inst(TypeBinder.BindA[B](), TypeBinder.BindB[A]())))
				b.Show(
					"the two inclusions and the inverse image identity",
					By(carriers, identity))
			}))
		inside := a.Have(
			"the target generators lie in the target carrier",
			"C ⊆ {E:set(prod(A, B)) | E ⊆ set_cross(Ω, V)}",
			BySets(cDef, rectangles))
		reverseInside := a.Have(
			"the reverse generators lie in the reverse carrier",
			"«swappedRects» ⊆ {E:set(prod(B, A)) | E ⊆ set_cross(V, Ω)}",
			BySets(rectangles))
		generated := a.Have(
			"the target rectangles generate the target sigma algebra",
			"product_sigma(Ω, S, V, T) = generated_sigma(set_cross(Ω, V), C)",
			By(cDef, ProductSigmaDef.At(Ω, S, V, T)))
		reverseGenerated := a.Have(
			"the reversed rectangles generate the reverse sigma algebra",
			"product_sigma(V, T, Ω, S) = generated_sigma(set_cross(V, Ω), «swappedRects»)",
			By(ProductSigmaDef.At(V, T, Ω, S)))
		reverseMeasurable := a.Have(
			"the reversed rectangles are measurable",
			"«swappedRects» ⊆ product_sigma(V, T, Ω, S)",
			By(
				reverseInside,
				reverseGenerated,
				At(sigma_algebra.GeneratedSigmaAlgebra.Inst[Prod[B, A]](), Krev, D)))
		into := a.Have(
			"the swap maps the reverse carrier into the target carrier",
			"image(«swap», set_cross(V, Ω)) ⊆ set_cross(Ω, V)",
			BySets(set_product.CrossSwap.At(Ω, V)))
		preimages := a.Have(
			"every target generator pulls back to a measurable reverse rectangle",
			"∀E:set(prod(A, B)). E ∈ C ⇒ preimage_on(set_cross(V, Ω), «swap», E) ∈ product_sigma(V, T, Ω, S)",
			Derive(func(b *Argument) {
				b.FixAs[Set[Prod[A, B]]]("E")
				member := b.Assume()
				s, t, rect := b.Unpack2As[Set[A], Set[B]](b.Simplified(member, Fwd(cDef)), "s", "t")
				reverse := b.Have(
					"the reversed generator belongs to the reverse sigma algebra",
					"set_cross(t, s) ∈ product_sigma(V, T, Ω, S)",
					BySets(rect, reverseMeasurable))
				b.Show(
					"its inverse image is that generator",
					By(Normalized, rect, reverse, rectangles.At(s, t)))
			}))
		reversed := a.Have(
			"the reverse product σ-algebra is a σ-algebra on the reverse carrier",
			"sigma_algebra_on(set_cross(V, Ω), product_sigma(V, T, Ω, S))",
			By(sigmaS, sigmaT, ProductSigmaProjections.At(V, T, Ω, S)))
		a.Show(
			"the generator criterion makes the swap measurable",
			By(reversed, inside, generated, into, preimages, MeasurableGenerated.At(Krev, Prev, K, C, swap)))
	}),
})}
